import numpy as np
from statsmodels.tsa.stattools import adfuller

def integration_order(x, max_d, alpha):
    y = np.asarray(x, dtype=float)
    for d in range(max_d + 1):
        if adfuller(y, autolag="AIC")[1] < alpha:
            return d             # the first d whose difference rejects a unit root
        y = np.diff(y)
    return None                  # still not stationary after max_d differences

