import numpy as np

def make_volume(seed, weeks=60):
    """Seeded daily volume in millions, Monday to Friday, with a weekly pattern."""
    rng = np.random.default_rng(seed)
    pattern = np.array([1.3, 1.0, 0.9, 0.95, 1.25])
    return np.tile(pattern, weeks) * np.exp(0.1 * rng.standard_normal(5 * weeks))
